import heapq


def stable_matching(proposers, receivers):
    receiver_rank = {
        receiver: {proposer: rank for rank, proposer in enumerate(preferences)}
        for receiver, preferences in receivers.items()
    }

    next_choice = {proposer: 0 for proposer in proposers}
    proposer_match = {}
    receiver_match = {}

    free = list(proposers)
    heapq.heapify(free)

    while free:
        proposer = heapq.heappop(free)
        preferences = proposers[proposer]

        receiver = preferences[next_choice[proposer]]
        next_choice[proposer] += 1

        current = receiver_match.get(receiver)

        if current is None:
            receiver_match[receiver] = proposer
            proposer_match[proposer] = receiver
        elif receiver_rank[receiver][proposer] < receiver_rank[receiver][current]:
            receiver_match[receiver] = proposer
            proposer_match[proposer] = receiver
            del proposer_match[current]
            heapq.heappush(free, current)
        else:
            heapq.heappush(free, proposer)

    return proposer_match
